function pancake_sort(nums) {
  const n = nums.length;

  // Function to flip the array from 0 to i
  function flip(arr, i) {
    let left = 0;
    let right = i;
    while (left < right) {
      [arr[left], arr[right]] = [arr[right], arr[left]];
      left++;
      right--;
    }
  }

  // Pancake sort algorithm
  for (let i = n - 1; i > 0; i--) {
    // Find the index of the maximum element in the unsorted part
    let maxIndex = 0;
    for (let j = 1; j <= i; j++) {
      if (nums[j] > nums[maxIndex]) {
        maxIndex = j;
      }
    }

    // Flip the array so that the maximum element is at the beginning
    flip(nums, maxIndex);

    // Flip the array so that the maximum element is at the end
    flip(nums, i);
  }

  return nums;
}

