function maxAverageOfPath(cost) {
  const n = cost.length;
  const dp = Array.from({ length: n }, () => Array(n).fill(0));

  // Initialize the first cell
  dp[0][0] = cost[0][0];

  // Fill the first row
  for (let j = 1; j < n; j++) {
    dp[0][j] = dp[0][j - 1] + cost[0][j];
  }

  // Fill the first column
  for (let i = 1; i < n; i++) {
    dp[i][0] = dp[i - 1][0] + cost[i][0];
  }

  // Fill the rest of the matrix
  for (let i = 1; i < n; i++) {
    for (let j = 1; j < n; j++) {
      dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
    }
  }

  // Calculate the maximum average
  let maxAverage = dp[n - 1][n - 1] / (n * n);

  return maxAverage;
}

function maxAverageOfPath(cost){
    const rows = cost.length;
    const cols = cost[0].length;
    const dp = Array.from({length: rows}, () => Array(cols).fill(0));
    const dirs = [[0, 1], [1, 0]]; // Directions: right, down

    // Initialize the dp array
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            dp[i][j] = cost[i][j];
        }
    }

    // Fill the dp array
    for (let i = 1; i < rows; i++) {
        for (let j = 1; j < cols; j++) {
            dp[i][j] = Math.max(dp[i][j], dp[i - 1][j] + cost[i][j]);
            dp[i][j] = Math.max(dp[i][j], dp[i][j - 1] + cost[i][j]);
        }
    }

    // Calculate the maximum average
    let maxAvg = -Infinity;
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            let sum = dp[i][j];
            let count = 1;
            for (let dir of dirs) {
                const x = i + dir[0];
                const y = j + dir[1];
                if (x >= 0 && x < rows && y >= 0 && y < cols) {
                    sum += dp[x][y];
                    count++;
                }
            }
            maxAvg = Math.max(maxAvg, sum / count);
        }
    }

    return maxAvg;
}

