function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = s = v = 0; // Black or white
    } else {
        s = delta / v;

        let rRatio = (max - r) / delta;
        let gRatio = (max - g) / delta;
        let bRatio = (max - b) / delta;

        if (r === max) {
            h = (gRatio - bRatio) / 6;
        } else if (g === max) {
            h = (bRatio - rRatio) / 6 + 1;
        } else {
            h = (rRatio - gRatio) / 6 + 2;
        }

        if (h < 0) h += 1;
        if (h > 1) h -= 1;
    }

    return [h * 360, s * 100, v * 100];
}

function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === r) {
    hue = (60 * ((g - b) / delta)) % 360;
  } else if (max === g) {
    hue = (60 * ((b - r) / delta)) + 120;
  } else if (max === b) {
    hue = (60 * ((r - g) / delta)) + 240;
  }

  let saturation;
  if (delta === 0) {
    saturation = 0;
  } else {
    saturation = (delta / max) * 100;
  }

  let value = max * 100;

  return [hue, saturation, value];
}

