function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));

  function dfs(row, col, path, count) {
    if (count === k) {
      return path;
    }

    visited[row][col] = true;
    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        const result = dfs(newRow, newCol, [...path, grid[newRow][newCol]], count + 1);
        if (result) {
          return result;
        }
      }
    }
    visited[row][col] = false;
    return null;
  }

  let minPath = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const result = dfs(i, j, [grid[i][j]], 1);
      if (result && (!minPath || comparePaths(result, minPath))) {
        minPath = result;
      }
    }
  }

  return minPath;
}

function comparePaths(path1, path2) {
  for (let i = 0; i < path1.length && i < path2.length; i++) {
    if (path1[i] !== path2[i]) {
      return path1[i] < path2[i];
    }
  }
  return path1.length < path2.length;
}

function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let visited = new Set();
    let minPath = [];

    const dfs = (x, y, path, steps) => {
        if (steps === k) {
            minPath.push(path);
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
                visited.add(`${nx},${ny}`);
                dfs(nx, ny, [...path, grid[nx][ny]], steps + 1);
                visited.delete(`${nx},${ny}`);
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    minPath.sort((a, b) => {
        for (let i = 0; i < a.length && i < b.length; i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return a.length - b.length;
    });

    return minPath[0];
}

