function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathLength = Infinity;
  const minPathValues = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        path.push(grid[nx][ny]);
        dfs(nx, ny, steps + 1);
        path.pop();
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      path.push(grid[i][j]);
      dfs(i, j, 1);
      path.pop();
      visited[i][j] = false;
    }
  }

  return minPathValues;
}

function minPath(grid, k) {
    const rows = grid.length;
    const cols = grid[0].length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(rows).fill().map(() => new Array(cols).fill(false));
    const path = [];

    function dfs(x, y, steps) {
        if (steps === k) {
            path.push(grid[x][y]);
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, steps + 1);
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            visited[i][j] = true;
            dfs(i, j, 1);
            visited[i][j] = false;
        }
    }

    path.sort((a, b) => a - b);
    return path;
}

