function rgb_to_hsv(r, g, b) {
  // Convert RGB to HSV
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h, s, v;

  if (delta === 0) {
    h = s = v = 0;
  } else {
    s = delta / max;

    const c = max / 255;
    h = (max === r) ? (g - b) / delta : (max === g) ? (b - r) / delta + 2 : (r - g) / delta + 4;

    h = h / 6;
    if (h < 0) h += 1;
    if (h > 1) h -= 1;
  }

  v = max / 255;

  return { h, s, v };
}

function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to the range [0, 1]
    r = r / 255;
    g = g / 255;
    b = b / 255;

    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;

    if (delta === 0) {
        h = 0;
    } else if (max === r) {
        h = (60 * ((g - b) / delta)) % 360;
    } else if (max === g) {
        h = (60 * ((b - r) / delta)) + 120;
    } else if (max === b) {
        h = (60 * ((r - g) / delta)) + 240;
    }

    s = (max === 0) ? 0 : delta / max;

    return {
        h: h,
        s: s,
        v: max
    };
}

