function get_total_number_of_sequences(m, n) {
  // Initialize the total count of sequences
  let totalSequences = 0;

  // Base case: If n is 1, there's only one sequence (the number itself)
  if (n === 1) {
    totalSequences = 1;
  } else {
    // Recursive case: For each element, there are m choices (from 2 to m)
    for (let i = 2; i <= m; i++) {
      // Recursively calculate the number of sequences for the remaining length (n-1)
      totalSequences += get_total_number_of_sequences(m, n - 1);
    }
  }

  return totalSequences;
}

function get_total_number_of_sequences(m, n){
    if (m < 2 || n < 1) {
        return 0;
    }

    let dp = new Array(n + 1).fill(0);
    dp[0] = 1; // There's one way to have an empty sequence (doing nothing)

    for (let i = 1; i <= n; i++) {
        for (let j = i; j <= m; j++) {
            dp[i] += dp[j - i];
        }
    }

    return dp[n];
}

