function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
  const path = [];
  let minPathLength = Infinity;
  let minPathValues = [];

  function dfs(x, y, steps) {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    visited[x][y] = true;
    path.push(grid[x][y]);

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        dfs(nx, ny, steps + 1);
      }
    }

    path.pop();
    visited[x][y] = false;
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 0);
    }
  }

  return minPathValues;
}

function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(rows).fill(0).map(() => new Array(cols).fill(false));

  const dfs = (i, j, path, steps) => {
    if (steps === k) {
      return path;
    }

    visited[i][j] = true;
    for (const [dx, dy] of directions) {
      const ni = i + dx;
      const nj = j + dy;
      if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && !visited[ni][nj]) {
        const newPath = [...path, grid[ni][nj]];
        const result = dfs(ni, nj, newPath, steps + 1);
        if (result) {
          return result;
        }
      }
    }
    visited[i][j] = false;
    return null;
  };

  let minPath = null;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      const result = dfs(i, j, [grid[i][j]], 1);
      if (result && (minPath === null || result.length < minPath.length)) {
        minPath = result;
      }
    }
  }

  return minPath;
}

