    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (i, j, pathLength, path) => {
        if (pathLength === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPath = [...path];
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const ni = i + dx;
            const nj = j + dy;
            if (ni >= 0 && ni < N && nj >= 0 && nj < N && !visited[ni][nj]) {
                visited[ni][nj] = true;
                dfs(ni, nj, pathLength + 1, [...path, grid[ni][nj]]);
                visited[ni][nj] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, 1, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    return minPath;
}

