  const memo = new Map();

  function helper(num){
    if (memo.has(num)) return memo.get(num);

    let result = num;
    for (let i = 2; i <= 5; i++){
      if (num % i === 0){
        result = Math.max(result, helper(num / i) + helper(num / i) + helper(num / i) + helper(num / i));
