function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let minPath = [];
    let visited = new Array(N).fill().map(() => new Array(N).fill(false));
    let path = [];

    const dfs = (i, j, steps) => {
        if (steps === k) {
            minPath = [...path];
            return;
        }

        for (const [dx, dy] of directions) {
            const x = i + dx;
            const y = j + dy;
            if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
                visited[x][y] = true;
                path.push(grid[x][y]);
                dfs(x, y, steps + 1);
                path.pop();
                visited[x][y] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                visited[i][j] = true;
                path.push(grid[i][j]);
                dfs(i, j, 1);
                path.pop();
                visited[i][j] = false;
            }
        }
    }

    return minPath;
}

function minPath(grid, k) {
