  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Set();
  const minPath = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      minPath.push(...grid[x][y].slice());
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
        visited.add(`${nx},${ny}`);
        dfs(nx, ny, steps + 1);
        visited.delete(`${nx},${ny}`);
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 0);
    }
  }

  return minPath.sort((a, b) => a - b);
}

