function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = s = v = 0;
    } else {
        s = delta / v;

        if (r === max) {
            h = (g - b) / delta;
        } else if (g === max) {
            h = 2 + (b - r) / delta;
        } else {
            h = 4 + (r - g) / delta;
        }

        h /= 6;
        if (h < 0) h += 1;
    }

    return {h: h * 360, s: s, v: v};
}

