function find_combinations(test_list) {
    // Helper function to generate all combinations
    function generate_combinations(arr, start, end, result) {
        if (start === end) {
            result.push(arr.slice());
            return;
        }
        for (let i = start; i <= end; i++) {
            arr[start], arr[i] = arr[i], arr[start];
            generate_combinations(arr, start + 1, end, result);
            arr[start], arr[i] = arr[i], arr[start];
        }
    }

    // Generate all possible combinations of sums
    let combinations = [];
    for (let i = 0; i < test_list.length; i++) {
        let sum = 0;
        let temp = [];
        for (let j = i; j < test_list.length; j++) {
            sum += test_list[j];
            temp.push(test_list[j]);
            generate_combinations(temp, 0, temp.length - 1, combinations);
        }
    }

    // Remove duplicate combinations
    let unique_combinations = new Set();
    for (let i = 0; i < combinations.length; i++) {
        let combination = combinations[i].join(',');
        unique_combinations.add(combination);
    }

    // Convert back to array of arrays
    return Array.from(unique_combinations, combination => combination.split(',').map(Number));
}

function find_combinations(test_list){
    let result = [];
    function backtrack(start, current, target) {
        if (current === target) {
            result.push([...current]);
            return;
        }
        if (current > target) {
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            current.push(test_list[i]);
            backtrack(i + 1, current, target);
            current.pop();
        }
    }
    backtrack(0, [], test_list.reduce((acc, val) => acc + val, 0));
    return result;
}

