function group_tuples(Input) {
  // Check if the input array is empty
  if (Input.length === 0) {
    return null;
  }

  // Initialize a set to store unique elements from the first array
  const uniqueElements = new Set();

  // Iterate through the first array to populate the set
  for (let i = 0; i < Input[0].length; i++) {
    uniqueElements.add(Input[0][i]);
  }

  // Iterate through the rest of the arrays to find common elements
  for (let i = 1; i < Input.length; i++) {
    const currentArray = Input[i];
    const commonElements = new Set();

    // Check if the current array contains any elements not in the unique elements set
    for (let j = 0; j < currentArray.length; j++) {
      if (!uniqueElements.has(currentArray[j])) {
        return null;
      }
      commonElements.add(currentArray[j]);
    }

    // If no common elements are found, return null
    if (commonElements.size === 0) {
      return null;
    }

    // Update the unique elements set with the common elements
    uniqueElements = new Set([...uniqueElements, ...commonElements]);
  }

  // Return the first common element found
  return uniqueElements.values().next().value;
}

