    // If no such digit is found, the number is the largest possible permutation
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit on the right side of i that is greater than digits[i]
    let j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of i
    digits.splice(i + 1);

    // Convert the array of digits back to a number
    return parseInt(digits.join(''), 10);
}

function rearrange_bigger(n){
    // Convert number to string to manipulate digits
    let numStr = n.toString();
    let len = numStr.length;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = len - 2;
    while (i >= 0 && numStr[i] >= numStr[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest permutation
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit to the right of i that is greater than numStr[i]
    let j = len - 1;
    while (j > i && numStr[j] <= numStr[i]) {
        j--;
    }

    // Swap the digits at positions i and j
    let temp = numStr[i];
    numStr[i] = numStr[j];
    numStr[j] = temp;

    // Reverse the digits to the right of i
    let left = i + 1;
    let right = len - 1;
    while (left < right) {
        let temp = numStr[left];
        numStr[left] = numStr[right];
        numStr[right] = temp;
        left++;
        right--;
    }

    // Convert the string back to number
    return parseInt(numStr, 10);
}

