    if (array.length === 0) return 1; // If the array is empty, the smallest missing number is 1

    let start = 0;
    let end = array.length - 1;

    while (start <= end) {
        let mid = Math.floor((start + end) / 2);

        // Check if the mid element is equal to its index
        if (array[mid] === mid + 1) {
            start = mid + 1; // If it is, the missing number is in the right half
        } else {
            end = mid - 1; // If it is not, the missing number is in the left half
        }
    }

    return start + 1; // The missing number is start + 1
}

function find_First_Missing(array){
  // Check if the array is empty or has only one element
  if (array.length === 0 || array.length === 1) {
    return 1; // The smallest missing number in an empty or single-element array is 1
  }

  // Initialize the expected starting number
  let expected = 1;

  // Iterate through the array
  for (let i = 0; i < array.length; i++) {
    // If the current number in the array matches the expected number, increment the expected number
    if (array[i] === expected) {
      expected++;
    } else {
      // If the current number in the array is greater than the expected number, return the expected number as the smallest missing number
      return expected;
    }
  }

  // If no missing number is found, return the length of the array plus one
  return array.length + 1;
}

