function max_sum_increasing_subseq(a, n, index, k){
    // Initialize a 2D array to store maximum sums
    const dp = new Array(n).fill(0).map(() => new Array(k + 1).fill(0));

    // Base case: If we're at the first element, the sum is the element itself
    dp[index][1] = a[index];

    // Fill the dp array
    for (let i = index + 1; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            // If the current element is greater than the previous element and we can include it in the subsequence
            if (a[i] > a[index] && j > 1) {
                dp[i][j] = Math.max(dp[i][j], dp[index][j - 1] + a[i]);
            }
            // If the current element is greater than the previous element and we can't include it in the subsequence
            else if (a[i] > a[index]) {
                dp[i][j] = Math.max(dp[i][j], dp[index][j]);
            }
            // If the current element is less than or equal to the previous element
            else {
                dp[i][j] = Math.max(dp[i][j], dp[index][j]);
            }
        }
    }

    // The maximum sum of increasing subsequence from prefix until i and including k
    return Math.max(...dp[n - 1]);
}

function max_sum_increasing_subseq(a, n, index, k) {
    const dp = new Array(n).fill(0);
    let maxSum = 0;

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            dp[i] = dp[index] + a[i];
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    for (let i = k + 1; i < n; i++) {
        if (a[i] > a[k]) {
            dp[i] = Math.max(dp[i], dp[k] + a[i]);
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    return maxSum;
}

