function rearrange_bigger(n){
    let digits = n.toString().split('');
    let sortedDigits = digits.slice().sort((a, b) => b - a);
    let index = 0;

    for (let i = 0; i < digits.length; i++) {
        if (digits[i] < sortedDigits[i]) {
            index = i;
            break;
        }
    }

    if (index === digits.length) {
        return -1; // No bigger number can be formed
    }

    let minDigit = sortedDigits[index];
    let minIndex = index;

    for (let i = index + 1; i < digits.length; i++) {
        if (digits[i] > minDigit && digits[i] < digits[minIndex]) {
            minDigit = digits[i];
            minIndex = i;
        }
    }

    let temp = digits[index];
    digits[index] = digits[minIndex];
    digits[minIndex] = temp;

    sortedDigits.splice(index + 1);

    return parseInt(digits.join(''));
}

function rearrange_bigger(n){
    // Convert the number to an array of digits
    let digits = n.toString().split('');

    // Sort the digits in descending order
    digits.sort((a, b) => b - a);

    // Find the index of the first digit that is smaller than the digit next to it
    let i;
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, the number is the largest possible permutation
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j;
    for (j = digits.length - 1; j >= 0; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the remaining digits in ascending order
    digits.splice(i + 1).sort((a, b) => a - b);

    // Convert the array of digits back to a number
    return parseInt(digits.join(''));
}

