function rgb_to_hsv(r, g, b){
    var max = Math.max(r, g, b);
    var min = Math.min(r, g, b);
    var delta = max - min;

    var h;
    var s;
    var v = max;

    if(delta === 0){
        h = 0;
        s = 0;
    } else {
        s = delta / v;

        var rc = (max - r) / delta;
        var gc = (max - g) / delta;
        var bc = (max - b) / delta;

        if(r === max){
            h = (gc - bc) / delta;
        } else if(g === max){
            h = 2 + (bc - rc) / delta;
        } else {
            h = 4 + (rc - gc) / delta;
        }

        h *= 60;
        if(h < 0){
            h += 360;
        }
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);

  // Calculate the value (V)
  const v = max;

  // Calculate the saturation (S)
  const s = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue (H)
  let h;
  if (max === min) {
    h = 0;
  } else if (r === max) {
    h = (g - b) / (max - min);
  } else if (g === max) {
    h = 2 + (b - r) / (max - min);
  } else {
    h = 4 + (r - g) / (max - min);
  }

  // Convert hue from radians to degrees
  h = (h * 180) / Math.PI;

  // Ensure hue is within the range [0, 360]
  h = h % 360;

  return { h, s, v };
}

