    // Initialize the maximum product of increasing subsequence found so far
    let max_so_far = 1;
    // Initialize the length of the array
    let n = arr.length;

    // Iterate through the array starting from the second element
    for (let i = 1; i < n; i++) {
        // Update max_so_far to be the maximum of max_so_far and arr[i]
        max_so_far = Math.max(max_so_far, arr[i]);
        // If arr[i] is greater than max_so_far, reset max_so_far to arr[i]
        if (arr[i] > max_so_far) {
            max_so_far = arr[i];
        }
        // Update max_product to be the maximum of max_product and max_so_far * arr[i]
        max_product = Math.max(max_product, max_so_far * arr[i]);
    }

    return max_product;
}

