function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  let rNorm = r / 255;
  let gNorm = g / 255;
  let bNorm = b / 255;

  // Find the maximum and minimum values
  let max = Math.max(rNorm, gNorm, bNorm);
  let min = Math.min(rNorm, gNorm, bNorm);

  // Calculate the difference between max and min
  let delta = max - min;

  // Calculate the hue
  let hue;
  if (delta === 0) {
    hue = 0;
  } else if (max === rNorm) {
    hue = (60 * ((gNorm - bNorm) / delta)) % 360;
  } else if (max === gNorm) {
    hue = (60 * ((bNorm - rNorm) / delta)) + 120;
  } else {
    hue = (60 * ((rNorm - gNorm) / delta)) + 240;
  }

  // Calculate the saturation
  let saturation;
  if (delta === 0) {
    saturation = 0;
  } else {
    saturation = (delta / max) * 100;
  }

  // Calculate the value
  let value = max * 100;

  return { hue, saturation, value };
}

function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in RGB
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the value (V)
  let v = max;

  // Calculate the saturation (S)
  let s = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue (H)
  let h;
  if (max === min) {
    h = 0;
  } else if (max === r) {
    h = (g - b) / (max - min);
  } else if (max === g) {
    h = 2 + (b - r) / (max - min);
  } else if (max === b) {
    h = 4 + (r - g) / (max - min);
  }

  // Convert hue to degrees
  h *= 60;

  // Ensure hue is within the range [0, 360)
  h %= 360;

  return [h, s, v];
}

