    const dp = new Array(n).fill().map(() => new Array(n).fill(Number.MAX_SAFE_INTEGER));
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    function dfs(row, col, steps, path) {
        if (steps === k) {
            dp[row][col] = path;
            return;
        }
        for (let i = 0; i < 4; i++) {
            const newRow = row + directions[i][0];
            const newCol = col + directions[i][1];
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && dp[newRow][newCol] === Number.MAX_SAFE_INTEGER) {
                dfs(newRow, newCol, steps + 1, path.concat([grid[newRow][newCol]]));
            }
        }
    }

    let minPath = [];
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (dp[i][j] === Number.MAX_SAFE_INTEGER) {
                dfs(i, j, 1, [grid[i][j]]);
            }
            if (dp[i][j] && dp[i][j].length === k) {
