  const n = test_list.length;

  function backtrack(start, currentSum, path) {
    if (currentSum === 0) {
      result.push([...path]);
      return;
    }

    for (let i = start; i < n; i++) {
      if (currentSum >= test_list[i]) {
        path.push(test_list[i]);
        backtrack(i + 1, currentSum - test_list[i], path);
        path.pop();
      }
    }
  }

  backtrack(0, 0, []);
  return result;
}

