function amicable_numbers_sum(limit) {
  function sumOfDivisors(n) {
    let sum = 1;
    for (let i = 2; i <= Math.sqrt(n); i++) {
      if (n % i === 0) {
        sum += i + (n / i);
      }
    }
    return sum;
  }

  let sum = 0;
  for (let i = 2; i <= limit; i++) {
    let divSum = sumOfDivisors(i);
    if (divSum > i && divSum <= limit && divSum !== i) {
      sum += i + divSum;
    }
  }

  return sum;
}

