function tri(n){
  if (n === 0) return [0];
  if (n === 1) return [0, 1];
  if (n === 2) return [0, 1, 2];

  let tribonacci = [0, 1, 2];
  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      tribonacci[i] = tribonacci[i - 1] + tribonacci[i - 2];
    } else {
      tribonacci[i] = tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i + 1];
    }
  }
  return tribonacci;
}

function tri(n){
    if (n < 0) return []; // Return an empty array for negative inputs
    if (n === 0) return [1]; // Base case: tri(0) = 1
    if (n === 1) return [1, 3]; // Base case: tri(1) = 1, tri(2) = 3
    if (n === 2) return [1, 3, 2]; // Base case: tri(2) = 1, tri(3) = 3, tri(4) = 2

    let sequence = [1, 3, 2]; // Initialize the sequence with the first three numbers
    for (let i = 3; i <= n; i++) {
        if (i % 2 === 0) {
            sequence.push(sequence[i - 1] + sequence[i - 2]);
        } else {
            sequence.push(sequence[i - 1] + sequence[i - 2] + sequence[i + 1]);
        }
    }
    return sequence;
}

